                                                l2_offset, s->cluster_size);

            if (ret < 0) {

                fprintf(stderr, "ERROR: Could not write L2 table; metadata "

                        "overlap check failed: %s\n", strerror(-ret));

                res->check_errors++;

                goto fail;

            }



            ret = bdrv_pwrite(bs->file, l2_offset, l2_table,

