            band->height   = b_height;

            band->pitch    = width_aligned;

            band->aheight  = height_aligned;

            band->bufs[0]  = av_mallocz(buf_size);

            band->bufs[1]  = av_mallocz(buf_size);

            band->bufsize  = buf_size/2;

